import {Store} from './store.mjs';
import {validateBank,validateEvents,derive,makeQueue,filterQuestions,breakdown,studyStreak,localDay} from './engine.mjs';
import {DriveSync} from './drive.mjs';
import {DriveSettings} from './drive-settings.mjs';
import {GoogleAccount,prepareGoogle,validClientId} from './auth.mjs';
import {AccountStorage,parseFolder,assertProgressOwner} from './account.mjs';
import {loginView,folderView,loadingView} from './access-views.mjs';
import {icon} from './icons.mjs';
import {homeView} from './home-view.mjs';
import {createSession,chooseAnswer,advanceSession} from './session.mjs';
import {FocusMode} from './focus-mode.mjs';
import {TemporaryStorage} from './temporary-storage.mjs';
import {restoreProgress} from './restore-progress.mjs';
const $=(selector,root=document)=>root.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(n,min,max)=>Math.max(min,Math.min(max,Number(n)||min));
const defaults={theme:'light',name:'Estudante',dailyGoal:10,folderId:'',onboardingDone:false,sidebarCollapsed:false};
let guest=false,restoration=null,restoreAuthorization=null;
let store,model,drive,view='home',session=null,selected=null,working=false,config={...defaults},toastTimer,auth,accountStorage,publicConfig={},loginError='',legacyAvailable=false;
const modes={smart:['Recomendadas','Um equilíbrio entre questões novas, erros e revisões.','spark'],random:['Aleatórias','Uma nova seleção, sem repetir questões na sessão.','shuffle'],new:['Não respondidas','Amplie o conteúdo que você já estudou.','book'],errors:['Revisar erros','Transforme as últimas respostas erradas em aprendizado.','repeat'],favorites:['Favoritas','Volte às questões que você quer ter por perto.','heart'],review:['Revisão espaçada','Questões marcadas e revisões que venceram hoje.','flag'],subject:['Por assunto','Escolha a disciplina, o assunto e o tópico.','filter'],exam:['Simulado','Responda no seu ritmo. O resultado aparece no final.','clock']};
const syncText={local:'Salvo neste dispositivo',pending:'Envio pendente',syncing:'Sincronizando…',synced:'Drive sincronizado',expired:'Reconectar Drive',error:'Falha na sincronização'};
const desktopLayout=matchMedia('(min-width: 701px)');
const focusMode=new FocusMode({document,desktop:desktopLayout,onChange:()=>{
  if((!auth?.profile&&!guest)||!store||!drive)return;
  render();
  $(focusMode.active?'[data-action=exit-focus]':'[data-action=toggle-focus]')?.focus({preventScroll:true});
},onUnavailable:()=>toast('Modo foco ativado. A tela cheia não está disponível neste navegador.')});
function saveConfig(){accountStorage?.setItem('foco:config',JSON.stringify(config));localStorage.setItem('foco:appearance',config.theme);}
function applyTheme(){document.documentElement.dataset.theme=config.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):config.theme;document.querySelector('meta[name=theme-color]').content=document.documentElement.dataset.theme==='dark'?'#212121':'#f8f9fc';}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function failure(error){console.error(error);toast(error?.name==='QuotaExceededError'?'O armazenamento local está cheio. Exporte seu progresso para preservar os dados.':error.message||'Não foi possível concluir. Tente novamente.');}
function refreshModel(){model=store.model();}
function navItem(key,label,i,count=''){return `<button class="nav-btn ${view===key?'selected':''}" data-action="nav" data-view="${key}" aria-label="${label}" title="${label}" ${view===key?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`;}
function shell(content){
  const profile=guest?{name:'Visitante',email:'Sessão temporária'}:auth.profile;
  return `<div class="shell ${view==='session'?'session':''} ${view==='home'?'home-shell':''} ${config.sidebarCollapsed?'sidebar-collapsed':''} ${focusMode.active?'focus-mode':''}">
  <aside class="sidebar" id="sidebar"><div class="logo"><span class="brand-mark">f.</span><span class="logo-word">foco</span></div><div class="logo-sub">IFSP & FATEC · SEU PRÓXIMO PASSO</div>
  <nav class="nav" aria-label="Navegação principal">${navItem('home','Visão geral','home')}${navItem('study','Estudar','play')}${navItem('banks','Meus bancos','book',model.banks.length)}${navItem('performance','Desempenho','chart')}${navItem('revision','Revisão','repeat',model.stats.review||'')}${navItem('settings','Ajustes','settings')}</nav>
  <div class="sidebar-bottom"><div class="sidebar-note">${icon('spark',16)}<strong>Uma questão de cada vez.</strong>A constância de hoje abre caminhos para amanhã.</div><div class="profile"><div class="avatar" title="${esc(config.name)}">${esc(config.name.slice(0,2).toUpperCase())}</div><div class="profile-info"><div class="profile-name">${esc(config.name)}</div><small title="${esc(profile.email)}">${esc(profile.email)}</small></div><button class="icon-btn" data-action="logout" aria-label="${guest?'Voltar ao login':'Sair da conta'}" title="${guest?'Voltar ao login':'Sair da conta'}">${icon('logout',16)}</button></div></div></aside>
  <div class="workspace"><header class="topbar"><div class="topbar-heading"><button class="icon-btn sidebar-toggle" data-action="toggle-sidebar" aria-label="${config.sidebarCollapsed?'Expandir menu':'Recolher menu'}" title="${config.sidebarCollapsed?'Expandir menu':'Recolher menu'}" aria-expanded="${!config.sidebarCollapsed}" aria-controls="sidebar">${icon(config.sidebarCollapsed?'panel-open':'panel-close',19)}</button><span class="top-label">Seu espaço de estudo</span></div><div class="mobile-logo"><span class="brand-mark">f.</span>foco</div><div class="flex">${guest?`<button class="guest-status" data-action="guest-login" aria-label="Modo visitante, sem salvar progresso. Voltar ao login" title="Entrar para salvar seus estudos">${icon('clock',16)}<span>Visitante · sem salvar</span></button>`:`<button class="sync-label" aria-label="Google Drive: ${syncText[drive.status]}" data-status="${drive.status}" data-action="nav" data-view="settings" title="${esc(drive.message||'Configurar sincronização com o Google Drive')}">${icon(drive.status==='synced'?'check':'cloud',16)}<span>${syncText[drive.status]}</span></button>`}<button class="icon-btn" data-action="toggle-theme" aria-label="Alternar tema claro e escuro" title="Alternar tema">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon',17)}</button><button class="icon-btn" data-action="logout" aria-label="${guest?'Voltar ao login':'Sair da conta'}" title="${guest?'Voltar ao login':'Sair da conta'}">${icon('logout',17)}</button>${view==='session'&&session&&!session.completed?`<button class="icon-btn focus-toggle" data-action="toggle-focus" aria-label="Ativar modo foco em tela cheia" title="Modo foco em tela cheia" aria-pressed="false">${icon('maximize',19)}</button>`:''}</div></header><div class="focus-toolbar"><span class="focus-caption">${icon('target',16)} Modo foco</span><div class="flex"><span class="focus-escape"><kbd>Esc</kbd> para sair</span><button class="icon-btn" data-action="toggle-theme" aria-label="${document.documentElement.dataset.theme==='dark'?'Ativar tema claro':'Ativar tema escuro'}" title="Alternar tema">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon',19)}</button><button class="btn small" data-action="exit-focus" title="Sair do modo foco · Esc">${icon('minimize',18)} Sair do foco</button></div></div>
  <main class="content" id="main" tabindex="-1">${guest?`<div class="guest-banner" role="status"><span>${icon('clock',16)} Modo visitante. Seu progresso será perdido ao sair ou recarregar.</span><button class="text-link" data-action="guest-login">Entrar com Google ${icon('arrow',13)}</button></div>`:''}${content}</main></div>
  <nav class="mobile-nav" aria-label="Navegação no celular">${[['home','Início','home'],['study','Estudar','play'],['banks','Bancos','book'],['performance','Desempenho','chart'],['settings','Ajustes','settings']].map(([k,l,i])=>`<button data-action="nav" data-view="${k}" class="${view===k?'selected':''}" ${view===k?'aria-current="page"':''}>${icon(i)}<span>${l}</span></button>`).join('')}</nav>
  <input type="file" id="bank-file" accept=".json,application/json" class="hidden" multiple><input type="file" id="progress-file" accept=".json,application/json" class="hidden"></div>`;
}
function heading(title,subtitle,extra=''){return `<div class="page-heading between"><div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
function stat(label,value,sub,i){return `<div class="stat"><div class="stat-top"><span>${label}</span>${icon(i,16)}</div><div class="stat-number">${value}</div><div class="stat-sub">${sub}</div></div>`;}
function progressBar(value){return `<div class="progress-track"><span style="width:${clamp(value,0,100)}%"></span></div>`;}
function empty(title,description,action=''){return `<div class="empty">${icon('book',28)}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function resumeSession(){return model.sessions.find(s=>s.id===config.activeSession&&!s.completed)||model.sessions.filter(s=>!s.completed&&!s.abandoned).at(-1);}
function weekChart(){
  const days=Array.from({length:7},(_,i)=>{const d=new Date(Date.now()-(6-i)*86400000);const a=model.answers.filter(e=>localDay(e.at)===localDay(d));return {day:d.toLocaleDateString('pt-BR',{weekday:'short',timeZone:'America/Sao_Paulo'}).replace('.',''),total:a.length,correct:a.filter(e=>e.correct).length};});
  const max=Math.max(5,...days.map(d=>d.total));
  return `<div class="week-chart" role="img" aria-label="Questões resolvidas nos últimos sete dias: ${days.map(d=>`${d.day} ${d.total}`).join(', ')}">${days.map(d=>`<div class="week-col" title="${d.total} respostas, ${d.correct} acertos"><div class="bar-wrap"><span class="bar" style="height:${d.total/max*100}%"></span></div><small>${d.day}</small></div>`).join('')}</div><div class="chart-caption"><span class="dot" style="color:var(--accent)"></span>${model.answers.length?'Cada sessão conta para sua evolução.':'Seu primeiro estudo começa a preencher este gráfico.'}</div>`;
}
function home(){return homeView({model,config,resume:resumeSession(),driveConnected:!!drive.token,driveStatus:drive.status,driveMessage:drive.message,guest});}
function study(){return heading('O que vamos estudar?','Escolha seu objetivo. O resto é uma questão de prática.')+`<div class="mode-grid">${Object.entries(modes).map(([key,[name,description,i]])=>`<button class="mode-card" data-action="start" data-mode="${key}">${icon(i,25)}<h3>${name}</h3><p>${description}</p><span class="badge">${filterQuestions(model,{mode:key}).length} questões disponíveis ${icon('arrow',12)}</span></button>`).join('')}</div><p class="study-tip">As sessões não repetem questões. As recomendadas equilibram conteúdo novo e revisão, com intervalos maiores após acertos consecutivos.</p>`;}
function banks(){
  return heading('Meus bancos de questões','Seu conteúdo, organizado do seu jeito.',`<button class="btn primary" data-action="import">${icon('plus',16)} Importar JSON</button>`)+`<section class="import-zone" id="drop-zone"><div class="flex">${icon('upload',25)}<h3>Um novo conteúdo começa aqui.</h3></div><p>Selecione ou arraste arquivos JSON. Não é preciso alterar o código.</p><div class="flex"><button class="btn small" data-action="import">Escolher arquivos</button><button class="btn small ghost" data-action="drive-banks">${icon('cloud',15)} Buscar no Drive</button><a class="btn small ghost" href="./docs/modelo-banco.json" download>Baixar modelo ${icon('download',14)}</a></div></section><div class="banks-grid">${model.banks.map(bank=>`<article class="card bank-card ${bank.enabled?'':'disabled'}"><div class="bank-row"><div class="book-icon">${icon('book',22)}</div><div><h3>${esc(bank.name)}</h3><p>${bank.questions.length} questões · ${[...new Set(bank.questions.map(q=>q.subject))].length} assuntos</p></div><span class="badge ${bank.enabled?'green':''}" style="margin-left:auto">${bank.enabled?'Ativo':'Desativado'}</span></div><p class="bank-description">${esc(bank.description||'Seu banco de questões para estudo e revisão.')}</p><div class="flex wrap" style="margin-bottom:20px">${[...new Set(bank.questions.map(q=>q.discipline))].map(d=>`<span class="pill">${esc(d)}</span>`).join('')}</div><div class="bank-actions"><button class="btn small primary" data-action="start" data-bank="${esc(bank.id)}" ${bank.enabled?'':'disabled'}>Estudar ${icon('arrow',14)}</button><button class="btn small" data-action="bank-toggle" data-bank="${esc(bank.id)}">${bank.enabled?'Desativar':'Ativar'}</button><button class="icon-btn" style="margin-left:auto;width:37px;height:37px" data-action="bank-export" data-bank="${esc(bank.id)}" aria-label="Exportar ${esc(bank.name)}">${icon('download',16)}</button><button class="icon-btn" style="width:37px;height:37px" data-action="bank-delete" data-bank="${esc(bank.id)}" aria-label="Excluir ${esc(bank.name)}">${icon('trash',16)}</button></div></article>`).join('')}</div>${model.banks.length?'':empty('Seu primeiro banco','Use o modelo JSON para organizar seu conteúdo.')}`;
}
function performanceRows(field){const rows=breakdown(model.answers,field);return rows.length?rows.map(r=>`<div class="perf-row"><div class="between"><span>${esc(r.label)}</span><strong>${r.accuracy}%</strong></div><div class="progress-track"><span class="${r.accuracy<60?'low':''}" style="width:${r.accuracy}%"></span></div><small>${r.correct} acertos · ${r.wrong} erros · ${r.total} tentativas</small></div>`).join(''):'<p class="muted" style="font-size:12px">Os resultados aparecerão após suas primeiras respostas.</p>';}
function performance(){const worst=model.questions.filter(q=>model.progress.get(q.key)?.wrong).sort((a,b)=>model.progress.get(b.key).wrong-model.progress.get(a.key).wrong).slice(0,5);const recent=model.answers.slice(-20);return heading('Entenda sua evolução','Veja o que já domina e onde vale investir mais atenção.')+`<div class="stat-grid">${stat('Taxa de acertos',`${model.stats.accuracy}%`,'Todas as tentativas do histórico','target')}${stat('Questões respondidas',model.stats.answered,`${model.stats.attempts} tentativas no total`,'book')}${stat('Últimas 20 respostas',`${recent.length?Math.round(recent.filter(a=>a.correct).length/recent.length*100):0}%`,`${recent.length} tentativas consideradas`,'chart')}${stat('Constância',studyStreak(model.answers),'Dias consecutivos de estudo','flame')}</div><div class="performance-grid"><section class="card"><h3>Por disciplina</h3>${performanceRows('discipline')}</section><section class="card"><h3>Por assunto</h3>${performanceRows('subject')}</section><section class="card"><h3>Por tópico</h3>${performanceRows('topic')}</section><section class="card"><h3>Sua última semana</h3>${weekChart()}<div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>Data</th><th>Respostas</th><th>Acertos</th></tr></thead><tbody>${[...new Set(model.answers.map(a=>localDay(a.at)))].slice(-7).reverse().map(d=>{const a=model.answers.filter(e=>localDay(e.at)===d);return `<tr><td>${d.split('-').reverse().join('/')}</td><td>${a.length}</td><td>${Math.round(a.filter(e=>e.correct).length/a.length*100)}%</td></tr>`;}).join('')||'<tr><td colspan="3">Nenhuma resposta registrada ainda.</td></tr>'}</tbody></table></div></section></div><section class="card" style="margin-top:22px"><h3 style="margin-bottom:18px">Questões que merecem atenção</h3>${worst.length?`<div class="revision-list">${worst.map(q=>`<div class="revision-row"><div><p>${esc(q.statement.slice(0,140))}${q.statement.length>140?'…':''}</p><small>${esc(q.subject)} · ${model.progress.get(q.key).wrong} erros no histórico</small></div><button class="btn small" data-action="single" data-key="${esc(q.key)}">Refazer ${icon('arrow',13)}</button></div>`).join('')}</div>`:'<p class="muted" style="font-size:12px">Quando houver erros, as questões aparecerão aqui para revisão.</p>'}</section>`;}
function revision(){const due=filterQuestions(model,{mode:'review'});const next=model.questions.filter(q=>model.progress.has(q.key)&&Date.parse(model.progress.get(q.key).due)>Date.now()).sort((a,b)=>model.progress.get(a.key).due.localeCompare(model.progress.get(b.key).due)).slice(0,5);return heading('Revisar é avançar.','Retome o conteúdo antes de ele ficar distante.',`<button class="btn primary" data-action="start" data-mode="review" ${due.length?'':'disabled'}>${icon('repeat',16)} Começar revisão</button>`)+`<div class="study-shortcuts" style="margin:0 0 26px"><button class="shortcut" data-action="start" data-mode="errors">${icon('repeat',22)}<span><strong>${model.stats.errors} erros para refazer</strong><small>A última resposta ainda pede atenção</small></span></button><button class="shortcut" data-action="start" data-mode="favorites">${icon('heart',22)}<span><strong>${model.stats.favorites} favoritas</strong><small>Suas questões de referência</small></span></button><div class="shortcut">${icon('clock',22)}<span><strong>${due.length} revisões para agora</strong><small>Marcadas ou com prazo vencido</small></span></div></div><h2 style="font-size:18px;margin-bottom:16px">Disponíveis para revisão</h2>${due.length?`<div class="revision-list">${due.map(q=>`<div class="revision-row"><div><p>${esc(q.statement.slice(0,140))}${q.statement.length>140?'…':''}</p><small>${esc(q.subject)} · ${model.flags.get(q.key)?.review?'Marcada por você':'Revisão vencida'}</small></div><button class="btn small" data-action="single" data-key="${esc(q.key)}">Revisar ${icon('arrow',13)}</button></div>`).join('')}</div>`:empty('Tudo em dia por aqui.','Marque questões durante o estudo ou retorne quando a próxima revisão vencer.', '<button class="btn" data-action="start">Continuar estudando</button>')}<section class="card" style="margin-top:25px"><h3 style="margin-bottom:15px">Próximas revisões</h3>${next.length?next.map(q=>`<div class="between" style="font-size:12px;margin:12px 0"><span>${esc(q.topic)}</span><span class="badge">${new Date(model.progress.get(q.key).due).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})}</span></div>`).join(''):'<p class="muted" style="font-size:12px">Seu calendário começa após a primeira resposta.</p>'}<p class="setting-note">Após um erro: revisão em 1 dia. Após acertos consecutivos: 1, 3, 7, 14, 30 e 60 dias. Questões marcadas ficam disponíveis até você retirar a marcação.</p></section>`;}
function guestSettings(){return heading('Seu espaço de estudo.','Você está usando uma sessão temporária.')+`<div class="settings-grid"><section class="card"><h3 style="margin-bottom:20px">Aparência</h3><div class="theme-options">${[['light','Claro','sun'],['dark','Escuro','moon'],['system','Sistema','system']].map(([key,label,i])=>`<button class="theme-option ${config.theme===key?'active':''}" data-action="theme" data-theme="${key}" aria-pressed="${config.theme===key}">${icon(i,21)}${label}</button>`).join('')}</div></section><section class="card"><h3>Modo visitante</h3><p class="setting-note">Você pode importar questões, responder e testar os modos de estudo. Respostas, favoritos, bancos e estatísticas existem apenas nesta sessão.</p><p class="setting-note">Ao sair ou recarregar a página, seu progresso será perdido. Entre com Google e conecte sua pasta do Drive para salvar os próximos estudos.</p><button class="btn primary" data-action="guest-login">Voltar ao login ${icon('arrow',15)}</button></section></div>`;}
function settings(){return heading('Um espaço do seu jeito.','Ajuste sua experiência e mantenha o progresso por perto.')+`<div class="settings-grid"><div class="stack"><section class="card"><h3>Aparência</h3><div class="theme-options">${[['light','Claro','sun'],['dark','Escuro','moon'],['system','Sistema','system']].map(([key,label,i])=>`<button class="theme-option ${config.theme===key?'active':''}" data-action="theme" data-theme="${key}" aria-pressed="${config.theme===key}">${icon(i,21)}${label}</button>`).join('')}</div><form id="profile-form" style="margin-top:24px"><div class="field"><label for="user-name">Como podemos chamar você?</label><input id="user-name" name="name" value="${esc(config.name)}" maxlength="80" required></div><div class="field"><label for="goal">Meta diária de questões</label><input id="goal" name="goal" type="number" value="${config.dailyGoal}" min="1" max="200" required></div><button class="btn small" type="submit">Salvar preferências</button></form></section><section class="card"><h3>Seu progresso</h3><p class="setting-note">Conta: <strong>${esc(auth.profile.email)}</strong>. Favoritos, respostas, bancos e preferências pertencem somente a este perfil.</p><p class="setting-note">Respostas, favoritos, revisões, bancos e sessões são salvos automaticamente neste navegador. Exporte um arquivo para levar uma cópia com você.</p><div class="settings-actions"><button class="btn small" data-action="export-progress">${icon('download',15)} Exportar progresso</button><button class="btn small" data-action="restore-progress">${icon('upload',15)} Restaurar JSON</button></div><p class="setting-note">A restauração aceita arquivos da mesma conta e une os históricos.</p>${legacyAvailable?'<button class="btn small" data-action="migrate-legacy">Recuperar meus estudos da versão anterior</button>':''}</section><section class="card"><h3>Atalhos para estudar</h3><div class="table-wrap"><table><tbody><tr><td>Selecionar alternativa</td><td><kbd>1</kbd> a <kbd>8</kbd> ou <kbd>A</kbd> a <kbd>H</kbd></td></tr><tr><td>Responder / próxima</td><td><kbd>Enter</kbd></td></tr><tr><td>Favoritar</td><td><kbd>F</kbd> + <kbd>Alt</kbd></td></tr><tr><td>Marcar para revisão</td><td><kbd>R</kbd> + <kbd>Alt</kbd></td></tr><tr><td>Pular questão</td><td><kbd>P</kbd> + <kbd>Alt</kbd></td></tr></tbody></table></div></section></div><div class="stack"><section class="card"><div class="between"><h3 style="margin:0">Google Drive</h3>${icon('cloud',21)}</div><div class="connection-card"><strong>${syncText[drive.status]}</strong>${esc(drive.message||'Ative a sincronização para recuperar seus estudos em outros dispositivos.')}</div><form id="drive-form"><div class="field"><label for="folder-id">Sua pasta do Google Drive</label><input id="folder-id" name="folderId" value="${esc(config.folderId)}" placeholder="https://drive.google.com/drive/folders/…" required><small>Use uma pasta do seu Meu Drive. Sua conta conectada é ${esc(auth.profile.email)}.</small></div><button class="btn small" type="submit">Salvar e conectar pasta</button></form><div class="settings-actions"><button class="btn primary small" data-action="connect-drive">${icon('cloud',16)}${drive.token?'Renovar acesso ao Drive':'Autorizar minha pasta'}</button><button class="btn small" data-action="sync" ${drive.token?'':'disabled'}>${icon('repeat',14)} Sincronizar</button>${drive.token?'<button class="btn small ghost" data-action="disconnect-drive">Desconectar</button>':''}</div><p id="folder-settings-status" class="setting-note" role="status" data-status="${drive.settings.status}">${esc(drive.settings.message)}</p><p class="setting-note">Entre com a mesma conta Google em outro dispositivo para recuperar esta pasta. O progresso é carregado após autorizar o Drive; o Google pode solicitar nova autorização. Nenhum token é salvo no navegador.</p><p class="setting-note">Os bancos JSON novos da pasta são importados ao conectar. Bancos existentes não são substituídos automaticamente. <button class="text-link" data-action="refresh-folder-banks">Buscar novos bancos agora</button></p>${drive.lastSync||accountStorage.getItem('foco:lastSync')?`<p class="setting-note">Último envio confirmado: ${new Date(drive.lastSync||accountStorage.getItem('foco:lastSync')).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</p>`:''}</section><section class="card"><h3>Novos conteúdos</h3><p class="setting-note">Peça questões em outros chats usando o mesmo formato. Cada arquivo vira um banco independente, com disciplina, assunto, tópico e comentários.</p><div class="download-links"><a href="./docs/modelo-banco.json" download>${icon('download',15)} Baixar modelo JSON</a><a href="./docs/questions.schema.json" download>${icon('file',15)} Baixar JSON Schema</a><a href="./docs/FORMATO_JSON.md" target="_blank" rel="noopener">Ler a documentação do formato ${icon('arrow',14)}</a><a href="./assets/lei-8112.json" download>Baixar as 10 questões da Lei nº 8.112/1990</a></div></section></div></div>`;}
function feedback(q,answer){const correct=answer===q.correctOption;return `<section class="feedback ${correct?'':'wrong'}" role="status"><div class="feedback-title">${icon(correct?'check':'x',19)}${correct?'Resposta correta. Bom trabalho!':answer?'Resposta incorreta. Vamos revisar.':'Questão não respondida.'}</div><p class="answer-line">${correct?`Alternativa correta: ${esc(q.correctOption)}.`:`Sua resposta: ${esc(answer||'não respondida')}. Alternativa correta: ${esc(q.correctOption)}.`}</p><p>${esc(q.explanation)}</p>${q.reference?`<div class="reference">${icon('file',14)} ${q.reference.url?`<a href="${esc(q.reference.url)}" target="_blank" rel="noopener noreferrer">${esc(q.reference.label)} ${icon('arrow',12)}</a>`:esc(q.reference.label)}</div>`:''}</section>`;}
function sessionView(){
  if(!session)return empty('Nenhuma sessão em andamento','Escolha um conteúdo para iniciar seu estudo.');
  const key=session.queue[session.index],q=model.questions.find(q=>q.key===key);
  if(!q)return empty('Conteúdo não disponível','O banco desta questão foi removido. Você pode voltar e iniciar outra sessão.','<button class="btn" data-action="pause">Voltar ao início</button>');
  const answer=session.answers[key],answered=answer!=null,exam=session.mode==='exam',show=answered&&!exam,f=model.flags.get(key)||{},stats=model.answers.filter(a=>a.sessionId===session.id);
  return `<div class="session-container"><div class="session-header"><button class="btn ghost small" data-action="pause">${icon('back',15)} Pausar e voltar</button><span class="muted">${modes[session.mode]?.[0]||'Estudo'} · <strong>Questão ${session.index+1} de ${session.queue.length}</strong></span></div><div class="session-progress">${progressBar(session.index/session.queue.length*100)}</div><article class="question-card"><div class="between"><div class="flex wrap"><span class="badge green">${esc(q.discipline)}</span><span class="badge">${({easy:'Fácil',medium:'Média',hard:'Difícil'})[q.difficulty]}</span></div><div class="question-tools"><button class="icon-btn ${f.favorite?'active':''}" data-action="flag" data-flag="favorite" aria-label="Favoritar questão" aria-pressed="${!!f.favorite}" title="Favoritar · Alt+F">${icon('heart',18)}</button><button class="icon-btn ${f.review?'active':''}" data-action="flag" data-flag="review" aria-label="Marcar para revisão" aria-pressed="${!!f.review}" title="Marcar para revisão · Alt+R">${icon('flag',18)}</button></div></div><div class="question-meta"><span>${esc(q.subject)}</span><span>›</span><span>${esc(q.topic)}</span><span class="muted" style="margin-left:auto">${esc(q.id)}</span></div><h1 class="question-statement">${esc(q.statement)}</h1><div class="options" role="group" aria-label="Alternativas">${q.options.map(o=>{const isSelected=(answer||selected)===o.id;const correct=show&&o.id===q.correctOption;const incorrect=show&&isSelected&&!correct;return `<button class="option ${isSelected?'selected':''} ${correct?'correct':''} ${incorrect?'incorrect':''}" data-action="select" data-option="${o.id}" aria-pressed="${isSelected}" ${answered?'disabled':''}><span class="option-letter">${o.id}</span><span>${esc(o.text)}</span>${correct?`<span class="option-result">${icon('check',17)}Correta</span>`:incorrect?`<span class="option-result">${icon('x',17)}Sua resposta</span>`:''}</button>`;}).join('')}</div>${show?feedback(q,answer):exam?'<p class="setting-note" style="margin-bottom:0">Modo simulado: comentários e gabarito aparecem somente ao concluir.</p>':''}<div class="question-actions">${answered?`<span class="muted" style="font-size:11px">${exam?'Resposta registrada.':guest?'Resposta registrada nesta sessão.':`${icon('check',14)} Progresso salvo.`}</span>`:'<button class="btn ghost" data-action="skip">Pular</button>'}<button class="btn primary" data-action="${answered?'next':'answer'}" ${!answered&&!selected?'disabled':''}>${answered?(session.index===session.queue.length-1?'Concluir sessão':'Próxima questão'):(exam?'Registrar resposta':'Responder')}${icon('arrow',16)}</button></div></article><div class="session-summary-bar">${exam?`<span>${Object.values(session.answers).filter(v=>v).length} respostas registradas</span>`:`<span><strong>${stats.filter(a=>a.correct).length}</strong> acertos</span><span><strong>${stats.filter(a=>!a.correct).length}</strong> erros</span><span><strong>${stats.length?Math.round(stats.filter(a=>a.correct).length/stats.length*100):0}%</strong> na sessão</span>`}<span class="keyboard-tip"><kbd>1</kbd>–<kbd>${q.options.length}</kbd> selecionar · <kbd>Enter</kbd> continuar</span></div></div>`;
}
function resultView(){const questions=session.queue.map(k=>model.questions.find(q=>q.key===k)).filter(Boolean),answered=questions.filter(q=>session.answers[q.key]),correct=answered.filter(q=>session.answers[q.key]===q.correctOption),wrong=answered.length-correct.length,skipped=questions.length-answered.length;const percentage=Math.round(correct.length/questions.length*100)||0;return `<div class="session-end"><span class="badge green">${icon('check',13)} SESSÃO CONCLUÍDA</span><h1 style="margin-top:18px">Mais um passo na sua preparação.</h1><p class="muted" style="font-size:12px;margin-top:10px">${session.mode==='exam'?'Confira o resultado e entenda cada resposta.':guest?'Seu resultado é temporário. Revise antes de sair.':'Seu progresso foi salvo. Aprender também é revisitar.'}</p><div class="result-ring"><strong>${percentage}%</strong><span>aproveitamento da sessão</span></div><div class="result-row"><div><strong style="color:var(--success)">${correct.length}</strong><span>acertos</span></div><div><strong style="color:var(--coral)">${wrong}</strong><span>erros</span></div><div><strong>${skipped}</strong><span>não respondidas</span></div></div><div class="flex wrap" style="justify-content:center"><button class="btn primary" data-action="start">Nova sessão ${icon('arrow',15)}</button>${wrong?'<button class="btn" data-action="session-errors">Revisar erros desta sessão</button>':''}<button class="btn ghost" data-action="nav" data-view="home">Voltar ao início</button></div><div class="results-list"><h2 style="font-size:18px;margin-bottom:15px">Seu estudo, questão por questão</h2>${questions.map((q,i)=>`<details class="result-item"><summary>${icon(session.answers[q.key]?session.answers[q.key]===q.correctOption?'check':'x':'clock',17)}<span>${i+1}. ${esc(q.topic)}</span><span class="badge" style="margin-left:auto">${session.answers[q.key]?session.answers[q.key]===q.correctOption?'Acerto':'Erro':'Pulada'}</span></summary><div class="result-body"><p>${esc(q.statement)}</p><p class="setting-note">Correta (${q.correctOption}): ${esc(q.options.find(o=>o.id===q.correctOption).text)}</p>${feedback(q,session.answers[q.key])}</div></details>`).join('')}</div></div>`;}
function render(){if(restoration){renderLoading();return;}if((!auth?.profile&&!guest)||!store||!drive){renderLogin();return;}refreshModel();const content=({home,study,banks,performance,revision,settings:()=>guest?guestSettings():settings(),folder:()=>folderView(auth.profile,config,!!drive.token),session:sessionView,result:resultView})[view]();$('#app').innerHTML=shell(content);document.title=`${({home:'Início',study:'Estudar',banks:'Meus bancos',performance:'Desempenho',revision:'Revisão',settings:'Ajustes',folder:'Conectar pasta',session:'Estudando',result:'Resultado'})[view]} · Foco`;bindFiles();bindForms();if(view==='settings'&&!guest)drive.prepare().catch(()=>{});}
function navigate(next){if(restoration)return;view=next;if(next!=='session')void focusMode.exit();selected=null;render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
function showDialog(html){const dialog=$('#dialog');dialog.innerHTML=html;dialog.showModal();return dialog;}
function closeDialog(){const d=$('#dialog');if(d.open)d.close();}
function confirmDialog(title,description,label='Confirmar'){return new Promise(resolve=>{const d=showDialog(`<div class="dialog-title"><h2 id="dialog-title">${esc(title)}</h2><p>${esc(description)}</p></div><div class="dialog-actions"><button class="btn" id="confirm-cancel">Cancelar</button><button class="btn primary" id="confirm-ok">${esc(label)}</button></div>`);let settled=false;const done=value=>{if(settled)return;settled=true;d.removeEventListener('cancel',cancel);closeDialog();resolve(value);};const cancel=e=>{e.preventDefault();done(false);};$('#confirm-cancel',d).onclick=()=>done(false);$('#confirm-ok',d).onclick=()=>done(true);d.addEventListener('cancel',cancel);});}
function startDialog(mode='smart',bankId=''){
  if(!model.banks.some(b=>b.enabled)){toast('Importe ou ative um banco para começar.');navigate('banks');return;}
  const enabled=model.banks.filter(b=>b.enabled),disciplines=[...new Set(model.questions.filter(q=>q.enabled).map(q=>q.discipline))].sort();
  const d=showDialog(`<form id="session-form"><div class="dialog-title"><h2 id="dialog-title">Seu próximo estudo.</h2><p>Escolha o conteúdo e a quantidade. Reserve este momento para você.</p></div><div class="form-grid"><div class="field"><label for="mode">Modo de estudo</label><select id="mode" name="mode">${Object.entries(modes).map(([k,[l]])=>`<option value="${k}" ${mode===k?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="count">Quantidade de questões</label><input id="count" type="number" name="count" value="10" min="1" max="5000" required></div></div><p class="field-label">Bancos selecionados</p>${enabled.map(b=>`<label class="bank-choice"><input type="checkbox" name="banks" value="${esc(b.id)}" ${!bankId||bankId===b.id?'checked':''}><span>${esc(b.name)}</span><small>${b.questions.length} questões</small></label>`).join('')}<div style="margin-top:18px" class="form-grid"><div class="field"><label for="discipline">Disciplina</label><select id="discipline" name="discipline"><option value="">Todas</option>${disciplines.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label for="subject">Assunto</label><select id="subject" name="subject"><option value="">Todos</option></select></div><div class="field"><label for="topic">Tópico</label><select id="topic" name="topic"><option value="">Todos</option></select></div></div><p class="eligible" id="eligible"></p><div id="session-error" class="form-error" role="alert"></div><div class="dialog-actions"><button class="btn" type="button" data-action="close-dialog">Cancelar</button><button class="btn primary" type="submit">Começar ${icon('arrow',15)}</button></div></form>`);
  const f=$('#session-form',d);const read=()=>({mode:f.mode.value,count:clamp(f.count.value,1,5000),banks:[...f.querySelectorAll('[name=banks]:checked')].map(i=>i.value),discipline:f.discipline.value,subject:f.subject.value,topic:f.topic.value});
  function available(){const n=filterQuestions(model,read()).length;$('#eligible',d).textContent=`${n} questões disponíveis. ${n<Number(f.count.value)?'A sessão usará todas as disponíveis.':''}`;}
  function cascade(source){const base=model.questions.filter(q=>q.enabled&&read().banks.includes(q.bankId));if(source==='banks'||source==='discipline'){const items=[...new Set(base.filter(q=>!f.discipline.value||q.discipline===f.discipline.value).map(q=>q.subject))].sort();f.subject.innerHTML='<option value="">Todos</option>'+items.map(x=>`<option>${esc(x)}</option>`).join('');}const items=[...new Set(base.filter(q=>(!f.discipline.value||q.discipline===f.discipline.value)&&(!f.subject.value||q.subject===f.subject.value)).map(q=>q.topic))].sort();f.topic.innerHTML='<option value="">Todos</option>'+items.map(x=>`<option>${esc(x)}</option>`).join('');available();}
  f.addEventListener('change',event=>{if(['banks','discipline','subject'].includes(event.target.name))cascade(event.target.name);else available();});f.count.addEventListener('input',available);cascade('banks');
  f.onsubmit=async event=>{event.preventDefault();if(working)return;const options=read();const queue=makeQueue(model,options);if(!queue.length){$('#session-error',d).textContent='Nenhuma questão encontrada. Ajuste os bancos, filtros ou modo de estudo.';return;}working=true;try{await newSession(queue,options.mode);closeDialog();navigate('session');}catch(e){failure(e);}finally{working=false;}};
}
async function newSession(queue,mode='smart'){
  const next=createSession(queue,mode);await store.add([{type:'session',session:next}]);session=next;config.activeSession=session.id;saveConfig();selected=null;
}
async function answer(){if(!selected||!session)return;const key=session.queue[session.index];if(session.answers[key])return;const q=model.questions.find(q=>q.key===key);const result=chooseAnswer(session,q,selected);await store.add(result.events);session=result.session;render();$('.feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
async function advance(skip=false){
  if(!session)return;const result=advanceSession(session,model.questions,skip);await store.add(result.events);session=result.session;selected=null;
  if(session.completed){config.activeSession=null;saveConfig();navigate('result');if(drive.token)drive.sync().catch(()=>{});}
  else{render();window.scrollTo(0,0);}
}
async function toggleFlag(flag){if(!session)return;const key=session.queue[session.index];await store.add([{type:'flag',key,flag,value:!model.flags.get(key)?.[flag]}]);render();toast(flag==='favorite'?(model.flags.get(key)?.favorite?'Questão favoritada.':'Favorito removido.'):(model.flags.get(key)?.review?'Questão marcada para revisão.':'Marcação removida.'));}
function download(name,document){const url=URL.createObjectURL(new Blob([JSON.stringify(document,null,2)],{type:'application/json'}));const link=documentElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function documentElement(tag){return document.createElement(tag);}
async function readJSON(file){if(file.size>10*1024*1024)throw new Error(`${file.name}: o limite é 10 MB.`);try{return JSON.parse(await file.text());}catch{throw new Error(`${file.name}: JSON inválido. Confira vírgulas, aspas e colchetes.`);}}
async function importBank(raw){const bank=validateBank(raw),old=model.banks.find(b=>b.id===bank.id);if(old&&!(await confirmDialog('Atualizar banco?',`Já existe “${old.name}” com este ID. O conteúdo será atualizado, preservando seu histórico de respostas. Mantenha IDs existentes apenas para as mesmas questões.`,'Atualizar')))return false;await store.add([{type:'bank',bank},{type:'bank-state',bankId:bank.id,value:'enabled'}]);refreshModel();return true;}
function bindFiles(){
  $('#bank-file').onchange=async event=>{const files=[...event.target.files];for(const file of files){try{if(await importBank(await readJSON(file)))toast(`Banco importado: ${file.name}`);}catch(e){failure(e);}}navigate('banks');};
  $('#progress-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{const doc=await readJSON(file);assertProgressOwner(doc,auth.profile.sub);const events=validateEvents(doc);await store.merge(events);render();toast('Históricos unidos. Seu progresso foi recuperado.');}catch(e){failure(e);}};
  const zone=$('#drop-zone');if(zone){zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag');};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=async e=>{e.preventDefault();zone.classList.remove('drag');for(const f of e.dataTransfer.files){try{if(await importBank(await readJSON(f)))toast(`Banco importado: ${f.name}`);}catch(error){failure(error);}}render();};}
}
function bindForms(){
  const profile=$('#profile-form');if(profile)profile.onsubmit=e=>{e.preventDefault();config.name=profile.elements.namedItem('name').value.trim()||'Estudante';config.dailyGoal=clamp(profile.elements.namedItem('goal').value,1,200);saveConfig();render();toast('Preferências salvas.');};
  for(const id of ['drive-form','folder-form']){const form=$(`#${id}`);if(!form)continue;form.onsubmit=async e=>{e.preventDefault();if(working)return;working=true;const button=form.querySelector('[type=submit]');button.disabled=true;try{const folder=parseFolder(form.elements.namedItem('folderId').value);await drive.connect(folder);config.onboardingDone=true;saveConfig();navigate(id==='folder-form'?'home':'settings');toast('Pasta salva na sua conta Google e progresso sincronizado.');}catch(error){if(id==='folder-form')$('#folder-error').textContent=error.message;else failure(error);}finally{working=false;button.disabled=false;}};}
}
async function driveBanks(){if(!drive.token){navigate('settings');toast('Conecte o Google Drive para buscar bancos na pasta.');return;}toast('Buscando arquivos JSON na pasta…');const files=await drive.bankFiles();if(!files.length){toast('Nenhum banco JSON encontrado na pasta.');return;}const d=showDialog(`<div class="dialog-title"><h2 id="dialog-title">Bancos no Google Drive</h2><p>Escolha um arquivo para importar.</p></div><div class="stack">${files.map(f=>`<button class="btn drive-file" data-id="${esc(f.id)}">${icon('file',17)} ${esc(f.name)}</button>`).join('')}</div><div class="dialog-actions"><button class="btn" data-action="close-dialog">Fechar</button></div>`);for(const b of d.querySelectorAll('.drive-file'))b.onclick=async()=>{b.disabled=true;try{const f=files.find(f=>f.id===b.dataset.id);const raw=await drive.readFile(f);closeDialog();if(await importBank(raw)){navigate('banks');toast('Banco do Drive importado.');}}catch(e){failure(e);b.disabled=false;}};}
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;
  if(action==='toggle-theme'||action==='theme'){try{config.theme=action==='theme'?target.dataset.theme:document.documentElement.dataset.theme==='dark'?'light':'dark';saveConfig();applyTheme();render();const selector=action==='theme'?`.theme-option[data-theme="${config.theme}"]`:focusMode.active?'.focus-toolbar [data-action=toggle-theme]':restoration||(!auth?.profile&&!guest)?'.entry-toolbar [data-action=toggle-theme]':'.topbar [data-action=toggle-theme]';$(selector)?.focus({preventScroll:true});}catch(error){failure(error);}return;}
  if(restoration){await handleRestorationAction(action);return;}
  if(!auth?.profile&&!guest&&!['login','guest'].includes(action))return;
  if(action==='exit-focus'){await focusMode.exit();return;}
  if(working)return;
  if(guest&&['connect-drive','disconnect-drive','sync','drive-banks','refresh-folder-banks','restore-progress','export-progress','migrate-legacy'].includes(action)){toast('Entre com Google para salvar ou recuperar seu progresso.');return;}
  try{
    if(action==='guest'){working=true;await openGuest();return;}
    if(action==='guest-login'){await logout();return;}
    if(action==='login'){working=true;loginError='';renderLogin();try{const result=await auth.authorize();await openAccount(result);}catch(error){loginError=error.message;drive?.close();auth.signOut();guest=false;restoration=null;accountStorage=null;store=null;drive=null;renderLogin();}return;}
    if(action==='logout'){await logout();return;}
    if(action==='toggle-sidebar'){config.sidebarCollapsed=!config.sidebarCollapsed;saveConfig();render();$('[data-action=toggle-sidebar]')?.focus({preventScroll:true});return;}
    if(action==='toggle-focus'){if(view==='session'&&session&&!session.completed)await focusMode.enter();return;}
    if(action==='skip-folder'){config.onboardingDone=true;saveConfig();navigate('home');return;}
    if(action==='migrate-legacy'){await migrateLegacy();return;}
    if(action==='refresh-folder-banks'){if(!drive.token)throw new Error('Autorize sua pasta primeiro.');const result=await drive.importNewBanks();render();toast(`${result.imported} novos bancos importados.`);return;}
    if(action==='nav'){navigate(target.dataset.view);return;}
    if(action==='start'){startDialog(target.dataset.mode||'smart',target.dataset.bank||'');return;}
    if(action==='close-dialog'){closeDialog();return;}
    if(action==='import'){$('#bank-file').click();return;}
    if(action==='restore-progress'){$('#progress-file').click();return;}
    if(action==='export-progress'){download(`foco-progresso-exportado-${localDay(Date.now())}.json`,store.export());return;}
    if(action==='bank-export'){const b=model.banks.find(b=>b.id===target.dataset.bank);const {enabled,...raw}=b;download(`${b.id}.json`,raw);return;}
    if(action==='bank-toggle'){const b=model.banks.find(b=>b.id===target.dataset.bank);await store.add([{type:'bank-state',bankId:b.id,value:b.enabled?'disabled':'enabled'}]);render();return;}
    if(action==='bank-delete'){const b=model.banks.find(b=>b.id===target.dataset.bank);if(await confirmDialog('Excluir este banco?',`“${b.name}” sairá da lista de estudos. Seu histórico será preservado. Você poderá importar o banco novamente.`, 'Excluir banco')){await store.add([{type:'bank-state',bankId:b.id,value:'deleted'}]);render();toast('Banco removido da lista.');}return;}
    if(action==='resume'){session=structuredClone(resumeSession());if(session){config.activeSession=session.id;saveConfig();navigate('session');}return;}
    if(action==='pause'){navigate('home');return;}
    if(action==='select'){selected=target.dataset.option;render();$(`[data-option="${selected}"]`)?.focus({preventScroll:true});return;}
    if(action==='single'){await newSession([target.dataset.key]);navigate('session');return;}
    if(action==='session-errors'){const queue=session.queue.filter(k=>{const q=model.questions.find(q=>q.key===k);return q&&session.answers[k]&&session.answers[k]!==q.correctOption;});await newSession(queue,'errors');navigate('session');return;}
    if(action==='flag'){working=true;await toggleFlag(target.dataset.flag);return;}
    if(action==='answer'){working=true;await answer();return;}
    if(action==='next'||action==='skip'){working=true;await advance(action==='skip');return;}
    if(action==='connect-drive'){working=true;toast('Abrindo a autorização do Google…');await drive.connect();config.onboardingDone=true;saveConfig();if(view==='folder')view='home';render();toast('Pasta salva na sua conta Google e progresso sincronizado.');return;}
    if(action==='disconnect-drive'){drive.disconnect();render();return;}
    if(action==='sync'){await drive.sync();render();toast('Históricos sincronizados com o Drive.');return;}
    if(action==='drive-banks'){await driveBanks();return;}
  }catch(error){if(action==='connect-drive')render();failure(error);}finally{working=false;if(!auth?.profile&&!guest&&!restoration)renderLogin();}
});
document.addEventListener('keydown',async event=>{
  if(restoration)return;
  if(event.key==='Escape'&&focusMode.active&&!$('#dialog').open){event.preventDefault();await focusMode.exit();return;}
  if(event.key==='Enter'&&event.target.closest?.('button')&&!['select','answer','next'].includes(event.target.dataset.action))return;
  if(view!=='session'||$('#dialog').open||working||event.target.matches('input,textarea,select'))return;
  const q=model.questions.find(q=>q.key===session.queue[session.index]);if(!q)return;
  try{
    if(event.altKey){if(event.key.toLowerCase()==='f'){event.preventDefault();await toggleFlag('favorite');}if(event.key.toLowerCase()==='r'){event.preventDefault();await toggleFlag('review');}if(event.key.toLowerCase()==='p'&&!session.answers[q.key]){event.preventDefault();await advance(true);}return;}
    if(event.ctrlKey||event.metaKey)return;
    const option=/^[1-8]$/.test(event.key)?q.options[Number(event.key)-1]?.id:q.options.find(o=>o.id===event.key.toUpperCase())?.id;
    if(option&&!session.answers[q.key]){event.preventDefault();selected=option;render();}
    if(event.key==='Enter'){event.preventDefault();working=true;if(session.answers[q.key])await advance();else if(selected)await answer();}
  }catch(e){failure(e);}finally{working=false;}
});
window.addEventListener('storage',event=>{if(!restoration&&auth?.profile&&accountStorage?.ownsKey(event.key)&&event.key.includes(':foco:v1:event:')){try{store.load();refreshModel();if(view!=='session'&&!$('#dialog').open)render();}catch(e){failure(e);}}});
window.addEventListener('online',()=>{if(!restoration&&drive?.token&&!drive.connecting)drive.sync().catch(()=>{});});
window.addEventListener('focus',()=>{if(!restoration&&drive?.token&&!drive.busy&&!drive.connecting)drive.sync().catch(()=>{});});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(config.theme==='system'){applyTheme();render();}});
function renderLogin(){
  if(restoration){renderLoading();return;}
  $('#app').innerHTML=loginView({ready:validClientId(auth?.clientId),busy:working,error:loginError,theme:document.documentElement.dataset.theme});document.title='Entrar · Foco';
  const form=$('#oauth-preview-form');if(form)form.onsubmit=e=>{e.preventDefault();const id=form.elements.namedItem('clientId').value.trim();if(!validClientId(id)){loginError='Informe apenas o ID público de um cliente OAuth Google Web.';renderLogin();return;}localStorage.setItem('foco:oauth-preview',id);auth.clientId=id;loginError='';renderLogin();prepareGoogle().catch(e=>{loginError=e.message;renderLogin();});};
}
async function openAccount(result){
  guest=false;restoreAuthorization=result;restoration=restoreProgress(null,{stage:'profile'});renderLoading();
  const profile=result.profile;accountStorage=new AccountStorage(localStorage,profile.sub);
  config={...defaults,...JSON.parse(accountStorage.getItem('foco:config')||'{}')};config.name=config.name==='Estudante'?profile.name:config.name;applyTheme();store=new Store(accountStorage);
  if(!store.events.length){const response=await fetch('./assets/lei-8112.json');if(!response.ok)throw new Error('Não foi possível carregar o banco inicial.');const raw=await response.json();await store.merge([{id:'builtin-lei-8112-v1',at:'2026-10-08T00:00:00.000Z',type:'bank',bank:validateBank(raw)}]);}
  legacyAvailable=false;
  if(publicConfig.legacyOwnerEmailSha256){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(profile.email.toLowerCase()));const hash=[...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join('');legacyAvailable=hash===publicConfig.legacyOwnerEmailSha256&&Array.from({length:localStorage.length},(_,i)=>localStorage.key(i)).some(k=>k?.startsWith('foco:v1:event:'));}
  refreshModel();const folderSettings=new DriveSettings(accountStorage,auth);drive=new DriveSync(store,config,auth,folderSettings);const ownDrive=drive;
  drive.addEventListener('config',()=>{if(drive===ownDrive)saveConfig();});
  folderSettings.addEventListener('status',()=>{if(drive!==ownDrive)return;const text=$('#folder-settings-status');if(text){text.textContent=folderSettings.message;text.setAttribute('data-status',folderSettings.status);}});
  store.addEventListener('change',()=>{if(drive===ownDrive){refreshModel();ownDrive.schedule();}});
  drive.addEventListener('status',()=>{if(drive!==ownDrive||!auth.profile)return;const label=$('.sync-label');if(label){label.dataset.status=ownDrive.status;label.title=ownDrive.message||syncText[ownDrive.status];label.setAttribute('aria-label',`Google Drive: ${syncText[ownDrive.status]}`);$('span',label).textContent=syncText[ownDrive.status];}});
  ownDrive.addEventListener('progress',()=>{if(drive===ownDrive&&restoration?.state==='loading'){restoration=restoreProgress(restoration,ownDrive.restoreProgress);renderLoading();}});
  await restoreAccount(result);
}
async function restoreAccount(result=restoreAuthorization){
  restoration=restoreProgress(null,{stage:'folder'});renderLoading();
  const folderSettings=drive.settings;
  try{
    if(!auth.canAppData){restoration={state:'permission',percent:20,detail:'Autorize o Google para localizar sua pasta e restaurar seus estudos em segurança.'};renderLoading();return;}
    const saved=await folderSettings.restore();if(saved){config.folderId=saved.folderId;config.onboardingDone=true;}
    if(config.folderId){
      if(!auth.canDrive){restoration={state:'permission',percent:25,detail:'Sua pasta foi encontrada. Autorize o acesso ao Drive para recuperar as questões e o progresso antes de continuar.'};renderLoading();return;}
      await drive.useAuthorization(result);
    }
    restoration=restoreProgress(restoration,{stage:'ready'});renderLoading();
    finishRestoration();
  }catch(error){restoration={state:'error',percent:restoration?.percent||20,detail:error.message};renderLoading();}
}
function renderLoading(){
  $('#app').innerHTML=loadingView({...restoration,theme:document.documentElement.dataset.theme,guest});
  document.title=guest?'Preparando questões · Foco':'Restaurando estudos · Foco';
}
function finishRestoration(){
  restoration=null;session=null;selected=null;view=config.onboardingDone||config.folderId?'home':'folder';saveConfig();render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});
}
async function handleRestorationAction(action){
  if(restoration.state==='loading'||working)return;
  try{
    if(action==='restore-local'){config.onboardingDone=true;drive.disconnect();finishRestoration();toast('Usando apenas os dados deste navegador. O Drive não foi restaurado.');return;}
    if(action==='restore-logout'){restoration=null;await logout();return;}
    if(!['restore-authorize','restore-retry'].includes(action))return;
    working=true;
    if(action==='restore-authorize'||Date.now()>=auth.expires-10000){
      restoration=restoreProgress(null,{stage:'access'});renderLoading();
      restoreAuthorization=await auth.authorize(true);
    }
    await restoreAccount(restoreAuthorization);
  }catch(error){restoration={state:'error',percent:restoration?.percent||20,detail:error.message};renderLoading();}
  finally{working=false;}
}
async function openGuest(){
  auth.signOut();guest=true;legacyAvailable=false;accountStorage=new TemporaryStorage();
  config={...defaults,name:'Visitante',onboardingDone:true,theme:localStorage.getItem('foco:appearance')||'light'};
  applyTheme();restoration=restoreProgress(null,{stage:'profile'});renderLoading();
  try{
    store=new Store(accountStorage);const response=await fetch('./assets/lei-8112.json');
    if(!response.ok)throw new Error('Não foi possível carregar as questões. Tente novamente.');
    await store.add([{type:'bank',bank:validateBank(await response.json())}]);
    drive=new DriveSync(store,config);store.addEventListener('change',refreshModel);
    finishRestoration();
  }catch(error){guest=false;restoration=null;store=null;drive=null;accountStorage=null;loginError=error.message;renderLogin();}
}

async function logout(){
  if(drive?.busy||drive?.connecting){toast('Aguarde a sincronização terminar para sair.');return;}
  if(drive?.token&&drive.status==='pending'){working=true;try{await drive.sync();}catch{toast('O envio não foi concluído. O progresso local desta conta foi preservado.');}}
  await focusMode.exit();drive?.close();auth.signOut();guest=false;restoration=null;restoreAuthorization=null;closeDialog();store=null;model=null;drive=null;accountStorage=null;session=null;selected=null;view='home';legacyAvailable=false;working=false;loginError='';config={...defaults,theme:localStorage.getItem('foco:appearance')||'light'};applyTheme();renderLogin();window.scrollTo(0,0);
}
async function migrateLegacy(){
  if(!legacyAvailable)return;
  if(!await confirmDialog('Recuperar estudos anteriores?','As respostas e os bancos da versão pessoal serão unidos a esta conta Google. A cópia original continuará preservada.','Recuperar'))return;
  const legacy=new Store(localStorage);await store.merge(legacy.events);const old=JSON.parse(localStorage.getItem('foco:config')||'{}');if(!config.folderId&&old.folderId)config.folderId=old.folderId;saveConfig();render();toast('Histórico anterior recuperado nesta conta.');
}
async function init(){
  try{
    config={...defaults,theme:localStorage.getItem('foco:appearance')||'light'};applyTheme();
    const response=await fetch('./app-config.json',{cache:'no-store'});if(response.ok)publicConfig=await response.json();
    const legacyConfig=JSON.parse(localStorage.getItem('foco:config')||'{}');
    auth=new GoogleAccount(publicConfig.googleClientId||localStorage.getItem('foco:oauth-preview')||legacyConfig.clientId||'');renderLogin();
    prepareGoogle().catch(error=>{if(!guest&&!auth.profile){loginError=error.message;renderLogin();}});
  }catch(error){loginError=error.message;auth=new GoogleAccount('');renderLogin();}
}
init();
